import json


def _is_vision_ref(ref):
    file_id = ref.get("file_id")
    content_type = ref.get("content_type")
    if not isinstance(file_id, str) or not isinstance(content_type, str):
        return False
    return content_type.startswith("image/") or content_type == "application/pdf"


async def run(args, state):
    files = state.get("files")
    if files is None:
        files = []
    if not isinstance(files, list):
        raise TypeError("shop_menu_agent: state.files must be a list")
    vision_files = [ref for ref in files if isinstance(ref, dict) and _is_vision_ref(ref)]
    state["files"] = vision_files
    content = state.get("content")
    has_text = isinstance(content, str) and content.strip() != ""
    if len(vision_files) > 0:
        state["chat_route"] = "files"
    elif has_text:
        state["chat_route"] = "text"
    else:
        state["response"] = json.dumps(
            {
                "sections": [],
                "failure_reason": "Пришлите текст меню или фото/PDF вложения.",
            },
            ensure_ascii=False,
            indent=2,
        )
        state["chat_route"] = "empty"
    return state

