import json
import re

ALLERGENS = frozenset({
    "gluten", "dairy", "egg", "fish", "shellfish", "nuts", "peanuts", "soy",
    "sesame", "mustard", "celery", "lupin", "molluscs", "sulphites",
})
MEASURE_UNITS = frozenset({"g", "ml", "pcs"})

EXTRACT_FOCUS_TEMPLATE = """\
Instead of a prose summary, for every ===PAGE n=== output exactly one JSON object \
(no markdown fences, no commentary) with keys "sections" and "failure_reason".
Rules for the JSON:
- sections: array of {name: string, items: array}. Preserve menu order.
- Item fields: shop_product_id (always null), name, description (string, empty if absent),
  price_minor (integer kopecks; omit dish if price unreadable), measure (int|null),
  measure_unit (g|ml|pcs; default g), ingredients (string[]), nutrition
  ({calories_kcal,proteins_g,fats_g,carbs_g}|null), allergens (from:
  gluten,dairy,egg,fish,shellfish,nuts,peanuts,soy,sesame,mustard,celery,lupin,molluscs,sulphites),
  photo ({file_id,page,x0,y0,x1,y1}|null).
- photo.file_id must be exactly FILE_ID below; photo.page is the n from ===PAGE n=== (0-based).
  x0,y0,x1,y1 are fractions 0..1 of the page (or of the full page image you see), top-left origin.
  Box only the dish food photo, not titles/prices/neighbors. No separate dish photo -> photo null.
- Skip phones, addresses, delivery notes, promos without a dish.
- failure_reason: empty string when the page has any dish; otherwise a short Russian reason.
- Invent nothing. Empty page -> {"sections":[],"failure_reason":""}.
FILE_ID=__FILE_ID__
USER_CONTEXT=__USER_CONTEXT__
"""


def _extract_json_object(text):
    if not isinstance(text, str):
        return None
    stripped = text.strip()
    if stripped == "":
        return None
    fence = re.search(r"```(?:json)?\s*([\s\S]*?)```", stripped, re.IGNORECASE)
    if fence is not None:
        stripped = fence.group(1).strip()
    start = stripped.find("{")
    end = stripped.rfind("}")
    if start < 0 or end <= start:
        return None
    try:
        payload = json.loads(stripped[start : end + 1])
    except json.JSONDecodeError:
        return None
    if not isinstance(payload, dict):
        return None
    return payload


def _normalize_photo(raw, *, file_id, page):
    if raw is None:
        return None
    if not isinstance(raw, dict):
        return None
    x0 = raw.get("x0")
    y0 = raw.get("y0")
    x1 = raw.get("x1")
    y1 = raw.get("y1")
    nums = (x0, y0, x1, y1)
    if not all(isinstance(v, (int, float)) for v in nums):
        return None
    if not (0.0 <= float(x0) < float(x1) <= 1.0 and 0.0 <= float(y0) < float(y1) <= 1.0):
        return None
    photo_file_id = raw.get("file_id")
    if not isinstance(photo_file_id, str) or photo_file_id.strip() == "":
        photo_file_id = file_id
    photo_page = raw.get("page")
    if not isinstance(photo_page, int) or photo_page < 0:
        photo_page = page
    return {
        "file_id": photo_file_id,
        "page": photo_page,
        "x0": float(x0),
        "y0": float(y0),
        "x1": float(x1),
        "y1": float(y1),
    }


def _normalize_item(raw, *, file_id, page):
    if not isinstance(raw, dict):
        return None
    name = raw.get("name")
    if not isinstance(name, str) or name.strip() == "":
        return None
    price = raw.get("price_minor")
    if not isinstance(price, int):
        return None
    description = raw.get("description")
    if description is None:
        description = ""
    if not isinstance(description, str):
        return None
    measure = raw.get("measure")
    if measure is not None and not isinstance(measure, int):
        return None
    measure_unit = raw.get("measure_unit")
    if not isinstance(measure_unit, str) or measure_unit not in MEASURE_UNITS:
        measure_unit = "g"
    ingredients = raw.get("ingredients")
    if ingredients is None:
        ingredients = []
    if not isinstance(ingredients, list) or not all(isinstance(x, str) for x in ingredients):
        return None
    nutrition = raw.get("nutrition")
    if nutrition is not None:
        if not isinstance(nutrition, dict):
            return None
        keys = ("calories_kcal", "proteins_g", "fats_g", "carbs_g")
        if any(k not in nutrition or not isinstance(nutrition[k], (int, float)) for k in keys):
            nutrition = None
        else:
            nutrition = {k: float(nutrition[k]) for k in keys}
    allergens = raw.get("allergens")
    if allergens is None:
        allergens = []
    if not isinstance(allergens, list):
        return None
    clean_allergens = [a for a in allergens if isinstance(a, str) and a in ALLERGENS]
    return {
        "shop_product_id": None,
        "name": name.strip(),
        "description": description,
        "price_minor": price,
        "measure": measure,
        "measure_unit": measure_unit,
        "ingredients": ingredients,
        "nutrition": nutrition,
        "allergens": clean_allergens,
        "photo": _normalize_photo(raw.get("photo"), file_id=file_id, page=page),
    }


def _merge_page(sections_by_name, order, payload, *, file_id, page):
    sections = payload.get("sections")
    if not isinstance(sections, list):
        return
    for section in sections:
        if not isinstance(section, dict):
            continue
        section_name = section.get("name")
        if not isinstance(section_name, str) or section_name.strip() == "":
            section_name = "Меню"
        else:
            section_name = section_name.strip()
        items_raw = section.get("items")
        if not isinstance(items_raw, list):
            continue
        normalized = []
        for item in items_raw:
            norm = _normalize_item(item, file_id=file_id, page=page)
            if norm is not None:
                normalized.append(norm)
        if len(normalized) == 0:
            continue
        if section_name not in sections_by_name:
            sections_by_name[section_name] = []
            order.append(section_name)
        sections_by_name[section_name].extend(normalized)


async def run(args, state):
    files = state.get("files")
    if files is None:
        files = []
    if not isinstance(files, list) or len(files) == 0:
        raise ValueError("shop_menu_agent: extract_menu requires vision files in state.files")
    content = state.get("content")
    if isinstance(content, str) and content.strip() != "":
        user_context = content.strip()
    else:
        user_context = "(none)"
    sections_by_name = {}
    order = []
    page_failures = []
    for ref in files:
        if not isinstance(ref, dict):
            continue
        file_id = ref.get("file_id")
        original_name = ref.get("original_name")
        if not isinstance(file_id, str) or not isinstance(original_name, str):
            continue
        focus = (
            EXTRACT_FOCUS_TEMPLATE
            .replace("__FILE_ID__", file_id)
            .replace("__USER_CONTEXT__", user_context)
        )
        envelope = await tools.read_file(
            names=[original_name],
            page_start=0,
            page_end=-1,
            page_summarizations=True,
            summarization_prompt=focus,
            nested_mode="parts",
            recursive=False,
        )
        if not isinstance(envelope, dict) or envelope.get("success") is not True:
            raise RuntimeError(f"shop_menu_agent: read_file failed for {original_name!r}")
        file_results = envelope.get("files")
        if not isinstance(file_results, list):
            raise TypeError("shop_menu_agent: read_file.files must be a list")
        for file_result in file_results:
            if not isinstance(file_result, dict):
                continue
            if file_result.get("success") is not True:
                err = file_result.get("error")
                raise RuntimeError(
                    f"shop_menu_agent: read_file error for {original_name!r}: {err}"
                )
            results = file_result.get("results")
            if not isinstance(results, list):
                continue
            for page_result in results:
                if not isinstance(page_result, dict):
                    continue
                page = page_result.get("page")
                if not isinstance(page, int):
                    page = 0
                payload = _extract_json_object(page_result.get("result"))
                if payload is None:
                    page_failures.append(f"{original_name}#p{page}")
                    continue
                reason = payload.get("failure_reason")
                if isinstance(reason, str) and reason.strip() != "":
                    page_failures.append(reason.strip())
                _merge_page(sections_by_name, order, payload, file_id=file_id, page=page)
    sections = [{"name": name, "items": sections_by_name[name]} for name in order]
    state["menu_sections"] = sections
    if len(sections) == 0:
        if page_failures:
            state["failure_reason"] = page_failures[0]
        else:
            state["failure_reason"] = "Не удалось распознать блюда во вложениях."
    else:
        state["failure_reason"] = ""
    entry_route = state.get("entry_route")
    if state["failure_reason"] == "":
        state["extract_route"] = "ok"
    elif entry_route == "work":
        state["extract_route"] = "work_fail"
    else:
        state["extract_route"] = "chat_fail"
    return state

