import json


async def run(args, state):
    sections = state["menu_sections"]
    if not isinstance(sections, list) or len(sections) == 0:
        raise ValueError("shop_menu_agent: menu_sections must be a non-empty array")
    job = state.get("shop_job")
    if isinstance(job, dict):
        attachment_file_ids = job.get("attachment_file_ids")
        if attachment_file_ids is None:
            attachment_file_ids = []
    else:
        files = state.get("files")
        if files is None:
            files = []
        if not isinstance(files, list):
            raise TypeError("shop_menu_agent: state.files must be a list")
        attachment_file_ids = [
            ref["file_id"]
            for ref in files
            if isinstance(ref, dict) and isinstance(ref.get("file_id"), str)
        ]
    if not isinstance(attachment_file_ids, list):
        raise TypeError("shop_menu_agent: attachment_file_ids must be a list")
    result = await tools.files_materialize_image_regions(
        sections=sections,
        attachment_file_ids=attachment_file_ids,
    )
    materialized = result["sections"]
    if not isinstance(materialized, list):
        raise TypeError("shop_menu_agent: materialize sections must be a list")
    state["menu_sections"] = materialized
    state["response"] = json.dumps(
        {"sections": materialized, "failure_reason": ""},
        ensure_ascii=False,
        indent=2,
    )
    return state
